    },
  },
  authfn: {
    packageName: "@authfn/docs",
    docsDir: "authfn/docs",
    kind: "sveltekit-cloudflare",
    zoneName: "authfn.com",
    hosts: {
      dev: "dev.authfn.com",
      live: "authfn.com",
    },
  },
};

export const environments = ["dev", "live"];

export function normalizeEnvironment(value) {
  const normalized = String(value ?? "").trim().toLowerCase();
  return environments.includes(normalized) ? normalized : null;
}

export function productIds() {
  return Object.keys(docsProducts);
}

export function existingProductIds() {
  return productIds().filter((productId) => hasDocsPackage(productId));
}

export function parseProducts(value, { existingOnly = false } = {}) {
  const raw = String(value ?? "all").trim();
  const available = existingOnly ? existingProductIds() : productIds();
  if (raw === "all") return available;

  const selected = raw.split(",").map((entry) => entry.trim()).filter(Boolean);
  if (selected.length === 0) {
    throw new Error("At least one docs product is required.");
  }

  for (const productId of selected) {
    if (!docsProducts[productId]) {
      throw new Error(`Invalid docs product: ${productId}`);
    }
    if (existingOnly && !hasDocsPackage(productId)) {
      throw new Error(`Docs package is missing for ${productId}: ${docsProducts[productId].docsDir}/package.json`);
    }
  }

  return [...new Set(selected)];
}

export function hasDocsPackage(productId) {
  return fs.existsSync(path.join(repoRoot, docsProducts[productId].docsDir, "package.json"));
}

export function workerName(productId, environment) {
  return `superfunctions-${productId}-docs-${environment}`;
}

export function routeDefinition(productId, environment) {
  const product = docsProducts[productId];
  return {
    product: productId,
    zoneName: product.zoneName,
    pattern: `${product.hosts[environment]}/docs*`,
    script: workerName(productId, environment),
  };
}

export function routesFor(environment, products) {
  return products.flatMap((productId) => {
    const route = routeDefinition(productId, environment);
    const product = docsProducts[productId];
    const aliases = product.routeAliases?.[environment] ?? [];
    return [
      route,
      ...aliases.map((host) => ({
        ...route,
        pattern: `${host}/docs*`,
      })),
    ];
  });
}

export function jsonArray(values) {
  return JSON.stringify([...new Set(values)]);
}


### scripts/cloudflare-docs/select-products.mjs

import process from "node:process";
import { spawnSync } from "node:child_process";
import {
  existingProductIds,
  jsonArray,
  normalizeEnvironment,
  parseProducts,
  productIds,
} from "./config.mjs";

const eventName = process.env.EVENT_NAME ?? "";
const inputEnvironment = process.env.INPUT_ENVIRONMENT ?? "dev";
const inputProduct = process.env.INPUT_PRODUCT ?? "all";
const refType = process.env.REF_TYPE ?? "";
const refName = process.env.REF_NAME ?? "";

let environment;
let products;

if (eventName === "workflow_dispatch") {
  environment = normalizeEnvironment(inputEnvironment);
  if (!environment) fail(`Invalid docs environment: ${inputEnvironment}`);
  if (environment === "live") assertLiveTag(refType, refName);
  products = parseProducts(inputProduct, { existingOnly: inputProduct === "all" });
} else if (refType === "tag") {
  environment = "live";
  const product = productFromLiveTag(refName);
  if (!product) fail(`Tag '${refName}' does not match a Superfunctions docs deploy target.`);
  products = product === "all" ? existingProductIds() : [product];
} else {
  environment = "dev";
  products = productsFromChangedFiles();
}

console.log(`environment=${environment}`);
console.log(`products=${jsonArray(products)}`);

function productsFromChangedFiles() {
  const before = resolveBeforeRef();
  const after = process.env.AFTER ?? "HEAD";
  const changedFiles = git(["diff", "--name-only", before, after]).split("\n").filter(Boolean);

  const selected = new Set();
  const selectExisting = (productId) => {
    if (existingProductIds().includes(productId)) selected.add(productId);
  };

  for (const file of changedFiles) {
    if (/^(package\.json|package-lock\.json|turbo\.json|scripts\/cloudflare-docs\/|\.github\/workflows\/superfunctions-docs-cloudflare-)/.test(file)) {
      return existingProductIds();
    }
    if (/^packages\/docs-theme\//.test(file)) {
      for (const productId of existingProductIds()) selectExisting(productId);
      continue;
    }
    if (file.startsWith("docsfn/") || file.startsWith("scripts/docs-site/")) {
      for (const productId of ["authfn", "devfn", "filefn"]) selectExisting(productId);
      continue;
    }
    if (/^datafn\/docs\//.test(file)) selectExisting("datafn");
    if (file.startsWith("devfn/docs/")) selectExisting("devfn");
    if (/^filefn\/docs\//.test(file)) selectExisting("filefn");
    if (/^searchfn\/docs\//.test(file)) selectExisting("searchfn");
    if (/^authfn\/docs\//.test(file)) selectExisting("authfn");
  }

  return [...selected];
}

function resolveBeforeRef() {
  const before = process.env.BEFORE ?? "";
  if (before && before !== "0000000000000000000000000000000000000000") {
    return before;
  }
  const after = process.env.AFTER ?? "HEAD";
  return git(["rev-parse", `${after}^`]);
}

function productFromLiveTag(tag) {
  if (/^superfunctions-docs-live-/.test(tag)) return "all";

  for (const productId of productIds()) {
    const accepted = [
      `superfunctions-docs-${productId}-live-`,
      `superfunctions-${productId}-docs-live-`,
    ];
    if (accepted.some((prefix) => tag.startsWith(prefix))) return productId;
  }

  return null;
}

function assertLiveTag(type, name) {
  if (type !== "tag" || !productFromLiveTag(name)) {
    fail("Live docs deploys must run from a Superfunctions docs live tag.");
  }
}

function git(args) {
  const result = spawnSync("git", args, {
    encoding: "utf8",
    stdio: ["ignore", "pipe", "pipe"],
  });
  if (result.status !== 0) {
    fail(result.stderr.trim() || `git ${args.join(" ")} failed`);
  }
  return result.stdout.trim();
}

function fail(message) {
  console.error(message);
  process.exit(1);
}


