    inputs:
      product:
        description: Docs product to deploy
        required: true
        type: choice
        default: all
        options:
          - all
          - datafn
          - filefn
          - searchfn
          - authfn
      environment:
        description: Docs environment to deploy
        required: true
        type: choice
        default: dev
        options:
          - dev
