    outputs:
      environment: ${{ steps.detect.outputs.environment }}
      products: ${{ steps.detect.outputs.products }}
    steps:
      - uses: actions/checkout@v4
        with:
          fetch-depth: 0

      - uses: actions/setup-node@v4
        with:
          node-version: 22

      - id: detect
        env:
          EVENT_NAME: ${{ github.event_name }}
          INPUT_ENVIRONMENT: ${{ github.event.inputs.environment }}
          INPUT_PRODUCT: ${{ github.event.inputs.product }}
          REF_TYPE: ${{ github.ref_type }}
          REF_NAME: ${{ github.ref_name }}
          BEFORE: ${{ github.event.before }}
          AFTER: ${{ github.sha }}
        shell: bash
        run: |
          set -euo pipefail
          node scripts/cloudflare-docs/select-products.mjs | tee /tmp/docs-deploy-detect.out
          cat /tmp/docs-deploy-detect.out >> "$GITHUB_OUTPUT"

  deploy:
    runs-on: ubuntu-latest
